def backfill_placement_order(apps, schema_editor):
    """Link pre-existing paid placements to the order that purchased them
    (ADR-0003). Exact match first on (campaign, start=interval_start);
    late-moderation shifts move start_at, so fall back to matching the charged
    duration against the campaign's order intervals. Unmatched rows (grants,
    legacy) stay null."""
    from datetime import timedelta

    Placement = apps.get_model("placements", "Placement")
    Order = apps.get_model("billing", "Order")

    linked = 0
    for order in Order.objects.exclude(interval_start_at__isnull=True):
        linked += Placement.objects.filter(
            campaign_id=order.campaign_id,
            source_type="paid",
            order__isnull=True,
            start_at=order.interval_start_at,
        ).update(order_id=order.pk)

    for placement in Placement.objects.filter(source_type="paid", order__isnull=True):
        charged = placement.end_at - placement.start_at
        for order in Order.objects.filter(
            campaign_id=placement.campaign_id,
            interval_start_at__isnull=False,
            interval_end_at__isnull=False,
        ).order_by("created_at"):
            if abs((order.interval_end_at - order.interval_start_at) - charged) <= timedelta(
                minutes=1
            ):
                placement.order_id = order.pk
                placement.save(update_fields=["order"])
                linked += 1
                break


